const resultados = [];

for (const item of $input.all()) {
  let pedido;

  // 1. Interpretar respuesta del agente
  try {
    pedido = typeof item.json.output === 'string'
      ? JSON.parse(item.json.output)
      : item.json.output;

    if (!pedido || typeof pedido !== 'object' ||
        Array.isArray(pedido)) {
      throw new Error('Respuesta inválida');
    }
  } catch (error) {
    resultados.push({
      json: {
        tipo: 'ERROR_VALIDACION',
        registrar: false,
        respuesta: 'No pude interpretar tu mensaje. Por favor, intentá nuevamente.',
        productos: []
      }
    });
    continue;
  }

  // 2. Consultas comerciales
  if (pedido.tipo !== 'PEDIDO') {
    resultados.push({
      json: {
        tipo: pedido.tipo || 'NO_RELEVANTE',
        registrar: false,
        respuesta: pedido.respuesta ||
          'La consulta requiere revisión comercial.',
        productos: []
      }
    });
    continue;
  }

  // 3. Normalizar campos
  const idCorreo = String(pedido.id_correo ?? '').trim();
  const cliente = String(pedido.cliente ?? '').trim();
  const email = String(pedido.email ?? '').trim();
  const fechaEntrega = String(pedido.fecha_entrega ?? '').trim();

  const faltantes = [];
  const productos = [];

  if (!idCorreo) faltantes.push('identificador del pedido');
  if (!cliente) faltantes.push('nombre del cliente');

  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    faltantes.push('correo electrónico válido');
  }

  if (!fechaEntrega) faltantes.push('fecha de entrega');

  // 4. Validar productos
  if (!Array.isArray(pedido.productos) ||
      pedido.productos.length === 0) {
    faltantes.push('productos y cantidades');
  } else {
    pedido.productos.forEach((p, indice) => {
      const producto = String(p?.producto ?? '').trim();
      const valor = p?.cajas;
      const cajas = valor === null ||
        valor === undefined ||
        String(valor).trim() === ''
          ? NaN
          : Number(valor);

      if (!producto) {
        faltantes.push(`nombre del producto ${indice + 1}`);
      }

      if (!Number.isInteger(cajas) || cajas <= 0) {
        faltantes.push(`cantidad de cajas del producto ${indice + 1}`);
      }

      if (producto && Number.isInteger(cajas) && cajas > 0) {
        productos.push({ producto, cajas });
      }
    });
  }

  // 5. Pedido incompleto: no registrar
  if (faltantes.length > 0) {
    const detalle = [...new Set(faltantes)].join(', ');

    const faltantesCliente = [...new Set(faltantes)]
      .filter(dato => dato !== 'identificador del pedido');

    const mensajeCliente = faltantesCliente.length > 0
      ? `Para procesar tu pedido necesitamos completar: ${faltantesCliente.join(', ')}.`
      : 'Tu pedido necesita una revisión antes de procesarse.';

    resultados.push({
      json: {
        tipo: 'PEDIDO',
        registrar: false,
        id_correo: idCorreo,
        cliente,
        email,
        fecha_entrega: fechaEntrega,
        productos,
        estado: 'INCOMPLETO',
        observaciones: `Datos faltantes o inválidos: ${detalle}`,
        respuesta: mensajeCliente
      }
    });

    continue;
  }

  // 6. Pedido completo
  resultados.push({
    json: {
      ...pedido,
      tipo: 'PEDIDO',
      registrar: true,
      id_correo: idCorreo,
      id_pedido: idCorreo,
      cliente,
      email,
      fecha_entrega: fechaEntrega,
      productos,
      estado: 'PENDIENTE_REVISION',
      observaciones:
        String(pedido.observaciones ?? '').trim() ||
        'Pendiente de revisión comercial.'
    }
  });
}

return resultados;
